"""Mock of IF-204, speech synthesis (protected). Complexity 2: returns short generated bytes.
It does not reproduce the sound of the real voice or the anime effect."""
import re

try:
    from .errors import ServiceError
except ImportError:
    from errors import ServiceError


class SpeechMock:
    def __init__(self, engine_down=False, lines=None):
        self.engine_down = engine_down
        self.lines = lines if lines is not None else {"hello": b"RIFFhello"}

    @staticmethod
    def _spoken(text):
        text = re.sub(r"<[^>]+>", "", text)                  # markup
        text = re.sub(r"\*[^*]*\*", "", text)                # stage directions such as *smiles*
        return re.sub(r"\s+", " ", text).strip()

    def synthesize(self, sentence):
        if self.engine_down:
            raise ServiceError("unavailable")
        spoken = self._spoken(sentence)
        if not spoken:
            raise ServiceError("empty_text")
        return {"audio": b"RIFF" + spoken.encode("utf-8"), "format": "wav", "spoken_text": spoken, "seconds": round(0.05 * len(spoken.split()), 2)}

    def voice_line(self, name):
        if name not in self.lines:
            raise ServiceError("no_line")
        return {"audio": self.lines[name], "format": "wav"}
